// ── פענוח ההודעה ─────────────────────────────────────────────
// מקבל את ה-webhook של Meta ומחלץ ממנו הודעה אחת בפורמט אחיד.
// Meta שולחת גם עדכוני סטטוס (sent / delivered / read) — הם מסוננים כאן.
// פלט: { phone, text, replyId, type, message_id, media_id, caption, profile_name, received_at }

const messages = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;

  for (const entry of body.entry ?? []) {
    for (const change of entry.changes ?? []) {
      const value = change.value ?? {};
      const contact = (value.contacts ?? [])[0] ?? {};

      for (const message of value.messages ?? []) {
        messages.push({ json: readMessage(message, contact) });
      }
    }
  }
}

// הודעה אחת לכל הרצה — כך כל ההפניות ל-first() בהמשך התרחיש נכונות
return messages.slice(0, 1);

function readMessage(message, contact) {
  let text = '';
  let replyId = ''; // מזהה הכפתור או השורה שנלחצו, למשל route_sales
  let mediaId = '';
  let caption = '';

  switch (message.type) {
    case 'text':
      text = message.text?.body ?? '';
      break;

    case 'interactive': {
      // לחיצה על שורה ברשימה או על כפתור תשובה
      const reply = message.interactive?.list_reply ?? message.interactive?.button_reply ?? {};
      replyId = reply.id ?? '';
      text = reply.title ?? '';
      break;
    }

    case 'button': // כפתור בתבנית
      text = message.button?.text ?? '';
      replyId = message.button?.payload ?? '';
      break;

    case 'image':
      caption = message.image?.caption ?? '';
      text = caption || '(תמונה)';
      mediaId = message.image?.id ?? '';
      break;

    default: // קול, מסמך, מיקום... — נרשם, ולא מטופל
      text = `[${message.type}]`;
  }

  return {
    phone: String(message.from ?? '').replace(/\D/g, ''),
    text: String(text).trim(),
    replyId,
    type: message.type,
    message_id: message.id,
    media_id: mediaId,
    caption,
    profile_name: contact.profile?.name ?? '',
    received_at: $now.setZone('Asia/Jerusalem').toFormat('yyyy-MM-dd HH:mm:ss'),
  };
}

// ── זיהוי לקוח ───────────────────────────────────────────────
// מחפש את הטלפון בלשונית customers וקובע באיזה שלב הלקוח:
//   new           — מספר שלא ראינו
//   awaiting_name — שאלנו לשם ועוד לא קיבלנו תשובה תקינה (שם ריק או "?")
//   known         — לקוח מוכר
// פלט: ההודעה + { stage, name, user_id, wa_saved }

const message = $('פענוח ההודעה').first().json;

// השוואה על ספרות בלבד: הגיליון עשוי לשמור את הטלפון כטקסט או כמספר
const digits = value => String(value ?? '').replace(/\D/g, '');

const customers = $input
  .all()
  .map(item => item.json)
  .filter(row => row?.phone !== undefined);
const row = customers.find(customer => digits(customer.phone) === message.phone);

const name = row ? String(row.name ?? '').trim() : '';

let stage = 'new';
if (row) {
  stage = name === '' || name === '?' ? 'awaiting_name' : 'known';
}

return [
  {
    json: {
      ...message,
      stage,
      name,
      user_id: row ? String(row.user_id ?? '') : '',
      wa_saved: row ? String(row.whatsapp_name ?? '').trim() : '', // שם הפרופיל שכבר שמור בגיליון
    },
  },
];

// ── השלמת שם פרופיל? ─────────────────────────────────────────
// לקוחות שנרשמו לפני שנוספה העמודה whatsapp_name — משלימים אותה פעם אחת.
// ענף מקביל: לא מעכב את התשובה ללקוח.
// פלט: שורה לעדכון ב-customers, או כלום

const customer = $input.first().json;

const needsUpdate = customer.stage !== 'new' && !customer.wa_saved && customer.profile_name;
if (!needsUpdate) return [];

return [{ json: { phone: customer.phone, whatsapp_name: customer.profile_name } }];

// ── שורת לקוח חדש ────────────────────────────────────────────
// שורה חדשה ללשונית customers. השם עדיין ריק — הבוט ישאל עליו מיד.
//   whatsapp_name — שם הפרופיל בוואטסאפ, כפי ש-Meta שולחת
//   name          — השם שהלקוח ימסור לבוט

const message = $input.first().json;

return [
  {
    json: {
      phone: message.phone,
      name: '',
      whatsapp_name: message.profile_name,
      created_at: message.received_at,
      user_id: '',
      source: 'whatsapp',
    },
  },
];

// ── הודעת פתיחה ──────────────────────────────────────────────
// הודעה ראשונה למספר חדש: היכרות ושאלה על השם.
// שאלת השם לא חוסמת: אם הלקוח פתח בשאלה, מבטיחים לחזור אליה.

const customer = $('זיהוי לקוח').first().json;

const openedWithQuestion =
  /[?？]/.test(customer.text) || /^(כמה|מה|איך|האם|יש|איפה|מתי|אפשר)\s/.test(customer.text);

let text = 'היי! אני העוזר של החנות 👋\nאיך קוראים לך?';

// TODO: לשמור את השאלה הראשונה ולענות עליה אחרי ההיכרות
if (openedWithQuestion) {
  text += '\n\n(אחרי שנכיר — שלחו לי את השאלה שוב ואענה מיד 🙂)';
}

return [{ json: { phone: customer.phone, route: 'onboarding', kind: 'text', text } }];

