// ── בדיקת שם ─────────────────────────────────────────────────
// בודק את השם ש-OpenAI חילץ מהתשובה. שלושה מצבים:
//   שם תקין                 → שומרים אותו
//   ניסיון ראשון שנכשל      → name = "?" ושואלים שוב (askAgain)
//   ניסיון שני שנכשל        → שם הפרופיל בוואטסאפ, ואם אין — "לקוח"
// פלט: { phone, name, whatsapp_name, askAgain }

const customer = $('זיהוי לקוח').first().json;

let name = '';
try {
  const answer = JSON.parse($input.first().json.choices[0].message.content);
  if (typeof answer.name === 'string') name = answer.name.trim();
} catch (error) {
  // תשובה לא תקינה מהמודל = לא התקבל שם
}

const isValid = name.length >= 2 && name.length <= 30 && !/[?\d@]/.test(name);
const profileName = String(customer.profile_name || '').trim();
const base = { phone: customer.phone, whatsapp_name: profileName };

if (isValid) {
  return [{ json: { ...base, name, askAgain: false } }];
}

const firstAttempt = customer.name === '';
if (firstAttempt) {
  return [{ json: { ...base, name: '?', askAgain: true } }];
}

return [{ json: { ...base, name: profileName || 'לקוח', askAgain: false } }];

// ── שדות לעדכון ──────────────────────────────────────────────
// רק העמודות של customers. בלי הסינון הזה, צומת הגיליון (autoMap) היה כותב
// לגיליון גם שדות פנימיים, כמו askAgain.

const { phone, name, whatsapp_name } = $input.first().json;

return [{ json: { phone, name, whatsapp_name } }];

// ── ברכה ותפריט ──────────────────────────────────────────────
// אחרי שהשם נשמר: ברכה בשם + רשימת האפשרויות.
// אם השם לא נקלט — שואלים שוב.

const result = $('בדיקת שם').first().json;

if (result.askAgain) {
  return [
    {
      json: {
        phone: result.phone,
        route: 'onboarding',
        kind: 'text',
        text: 'לא הצלחתי לקלוט את השם 🙂 איך לפנות אלייך?',
      },
    },
  ];
}

// המזהים (route_...) חוזרים אלינו כשהלקוח בוחר שורה — ראו "הקשר ובחירה"
const MENU = [
  { id: 'route_sales', title: 'מכירות', description: 'מוצרים, מחירים ומלאי' },
  { id: 'route_support', title: 'שירות לקוחות', description: 'בעיה בהזמנה או במוצר' },
  { id: 'route_fitness', title: 'ייעוץ כושר', description: 'טיפים כלליים לאימון' },
  { id: 'route_shipping', title: 'מידע על משלוח', description: 'איפה ההזמנה שלי?' },
  { id: 'route_signup', title: 'הרשמה לאפליקציה', description: 'הנחת כושר למתאמנים' },
];

const hello = result.name === 'לקוח' ? 'נעים מאוד!' : `נעים מאוד, ${result.name}! 😊`;

return [
  {
    json: {
      phone: result.phone,
      route: 'onboarding',
      kind: 'list',
      button: 'אפשרויות',
      text: [
        hello,
        'אני העוזר של החנות. אפשר לשאול אותי על מוצרים, מחירים ומשלוחים. במה אפשר לעזור?',
      ].join('\n'),
      rows: MENU,
    },
  },
];

// ── הקשר ובחירה ──────────────────────────────────────────────
// לקוח מוכר: מצמיד להודעה את הקטלוג, את המוצר האחרון שנבחר ואת זיכרון השיחה,
// ומחליט מה לעשות — בלי מודל, כשאפשר:
//   route    — נבחרה שורה בתפריט (route_sales ...)
//   product  — נבחר מוצר מרשימה (prod_P-001), או שההודעה מהאתר מכילה קוד מוצר
//   order    — נלחץ "להזמין" (order_P-001)
//   confirm  — נלחץ "כן, להזמין" (confirm_P-001_q2 = מוצר P-001, כמות 2)
//   cancel   — נלחץ "ביטול"
//   image    — הלקוח שלח תמונה
//   classify — טקסט חופשי: פקיד הקבלה (OpenAI) יסווג אותו
// פלט: הלקוח + { action, route, product, qty, ctxProduct, catalog, history, fromMenu }

const customer = $('זיהוי לקוח').first().json;
const store = $getWorkflowStaticData('global'); // זיכרון של התרחיש בין הרצות
const DAY = 24 * 60 * 60 * 1000;

// ── קטלוג: רק מוצרים פעילים ──
const catalog = $input
  .all()
  .map(item => item.json)
  .filter(row => row.id && String(row.active).trim() === 'כן')
  .map(row => ({
    id: String(row.id),
    name: String(row.name),
    category: String(row.category),
    description: String(row.description),
    price: Number(row.price_ils),
    stock: Number(row.stock),
    image: String(row.image || '').trim(),
  }));

// ── המוצר האחרון שהלקוח צפה בו (נשמר ל-24 שעות) ──
const context = (store.ctx || {})[customer.phone] || {};
const ctxProduct = context.at && Date.now() - context.at < DAY ? context.product : null;

// ── מה לעשות ──
// כפתורים ורשימות מחזירים מזהה עם קידומת — כך יודעים מה נלחץ בלי לשאול את המודל
const replyId = String(customer.replyId || '');
let action = 'classify';
let route = null;
let product = null;
let qty = 1;

if (replyId.startsWith('route_')) {
  action = 'route';
  route = replyId.slice('route_'.length);
} else if (replyId.startsWith('prod_')) {
  action = 'product';
  product = replyId.slice('prod_'.length);
} else if (replyId.startsWith('order_')) {
  action = 'order';
  product = replyId.slice('order_'.length);
} else if (replyId.startsWith('confirm_')) {
  action = 'confirm';
  const [, id, count] = replyId.slice('confirm_'.length).match(/^(.+?)(?:_q(\d+))?$/);
  product = id;
  qty = Number(count || 1);
} else if (replyId === 'cancel') {
  action = 'cancel';
} else if (customer.type === 'image' && customer.media_id) {
  // תמונה מלקוח מוכר = פנייה לשירות (מוצר פגום, חבילה)
  action = 'image';
} else {
  // "שאל בוואטסאפ" באתר שולח "שאלה על <מוצר> (P-004)" — קוד מוכר פותח את כרטיס המוצר
  const code = String(customer.text || '').match(/\((P-\d{3})\)/);
  if (code && catalog.some(item => item.id === code[1])) {
    action = 'product';
    product = code[1];
  }
}

// ── זיכרון שיחה: 8 ההודעות האחרונות מ-24 השעות האחרונות (נכתבות ב"רישום שיחה") ──
const history = ((store.hist || {})[customer.phone] || [])
  .filter(entry => Date.now() - entry.at < DAY)
  .slice(-8)
  .map(entry => {
    const who = entry.role === 'user' ? 'לקוח' : 'בוט';
    return `${who}: ${entry.text.replace(/\s+/g, ' ').slice(0, 300)}`;
  })
  .join('\n');

return [
  {
    json: {
      ...customer,
      action,
      route,
      product,
      qty,
      ctxProduct,
      catalog,
      history,
      fromMenu: action === 'route',
    },
  },
];

// ── מסלול מהסיווג ────────────────────────────────────────────
// קורא את התשובה של פקיד הקבלה (OpenAI): {"route": "...", "qty": ...}.
// מסלול לא מוכר → unclear. בקשת הזמנה בלי מוצר בהקשר → sales, כדי שהלקוח יבחר.
// פלט: כל מה שהגיע מ"הקשר ובחירה" + { route, qty, product }

const input = $('הקשר ובחירה').first().json;
const ROUTES = ['sales', 'order', 'support', 'fitness', 'shipping', 'signup', 'unclear'];

let answer = {};
try {
  answer = JSON.parse($input.first().json.choices[0].message.content);
} catch (error) {
  // תשובה לא תקינה מהמודל → unclear
}

let route = ROUTES.includes(answer.route) ? answer.route : 'unclear';

// כמות: מספר שלם בין 1 ל-10
const qty = Math.min(10, Math.max(1, Math.round(Number(answer.qty) || 1)));

// "טוב תזמין" בלי מוצר בהקשר — מציגים את הקטלוג
if (route === 'order' && !input.ctxProduct) route = 'sales';

return [
  {
    json: {
      ...input,
      route,
      qty,
      product: route === 'order' ? input.ctxProduct : null,
    },
  },
];

