// ── תשובת מכירות ─────────────────────────────────────────────
// סוכן המכירות (OpenAI) מחזיר {"text", "product_ids"}. כאן בונים ממנו רשימת מוצרים.
// מחירים ומלאי נלקחים מהקטלוג — לא ממה שהמודל כתב.

const customer = $('זיהוי לקוח').first().json;
const { catalog } = $('ניתוב').first().json;

let text = 'הנה המוצרים שלנו 👇 בחרו מוצר כדי לראות פרטים ולהזמין.';
let ids = [];
try {
  const answer = JSON.parse($input.first().json.choices[0].message.content);
  if (typeof answer.text === 'string' && answer.text.trim()) text = answer.text.trim();
  if (Array.isArray(answer.product_ids)) ids = answer.product_ids.map(String);
} catch (error) {
  // תשובה לא תקינה מהמודל → טקסט ברירת המחדל וכל הקטלוג
}

// רק מזהים שקיימים בקטלוג. אם המודל לא בחר אף מוצר — כל הקטלוג
let products = ids.map(id => catalog.find(item => item.id === id)).filter(Boolean);
if (products.length === 0) products = catalog;

return [
  {
    json: {
      phone: customer.phone,
      route: 'sales',
      kind: 'list',
      button: 'לבחירת מוצר',
      section: 'מוצרים',
      text,
      rows: productRows(products),
    },
  },
];

// שורות לרשימה בוואטסאפ: עד 10, עם מחיר ומצב מלאי
function productRows(list) {
  return list.slice(0, 10).map(item => ({
    id: 'prod_' + item.id,
    title: item.name,
    description: `${shekels(item.price)} · ${stockLabel(item.stock)}`,
  }));
}
function stockLabel(stock) {
  if (stock <= 0) return 'אזל';
  if (stock <= 5) return 'נשארו מעט';
  return 'במלאי';
}
function shekels(amount) {
  return Math.round(amount * 100) / 100 + ' ₪';
}

// ── פרטי מוצר ────────────────────────────────────────────────
// כרטיס מוצר: תמונה, תיאור, מחיר ומלאי, עם כפתורים [להזמין] [מוצרים נוספים].
// המוצר נשמר כ"מוצר בהקשר" ל-24 שעות — כדי ש"תזמין" בטקסט חופשי יידע למה הכוונה.

const customer = $('זיהוי לקוח').first().json;
const { catalog, product: productId } = $input.first().json;
const PRODUCT_IMAGES =
  'https://owvvkwxzjuglrfeuujez.supabase.co/storage/v1/object/public/products/';

const product = catalog.find(item => item.id === productId);

if (!product) {
  return [
    {
      json: {
        phone: customer.phone,
        route: 'sales',
        kind: 'list',
        button: 'לבחירת מוצר',
        section: 'מוצרים',
        text: 'המוצר הזה כבר לא זמין. אלה המוצרים שיש לנו כרגע 👇',
        rows: productRows(catalog),
      },
    },
  ];
}

rememberProduct(customer.phone, product.id);

const inStock = product.stock > 0;
const lines = [
  `*${product.name}*`,
  product.description,
  '',
  `מחיר: ${shekels(product.price)} · ${stockLabel(product.stock)}`,
];
if (!inStock) lines.push('', 'המוצר אזל כרגע.');

const buttons = inStock
  ? [
      { id: 'order_' + product.id, title: 'להזמין' },
      { id: 'route_sales', title: 'מוצרים נוספים' },
    ]
  : [{ id: 'route_sales', title: 'מוצרים נוספים' }];

return [
  {
    json: {
      phone: customer.phone,
      route: 'product',
      kind: 'buttons',
      image: await imageUrl(product, this.helpers),
      text: lines.join('\n'),
      buttons,
    },
  },
];

// תמונה: כתובת מלאה מהגיליון, או שם קובץ בדלי הציבורי products ב-Supabase.
// לפני השליחה בודקים שהתמונה קיימת: תמונה חסרה מכשילה את כל ההודעה אצל Meta.
async function imageUrl(item, helpers) {
  if (!item.image) return null;
  const url = /^https?:\/\//.test(item.image)
    ? item.image
    : PRODUCT_IMAGES + item.image.replace(/\.(png|jpeg)$/i, '.jpg');
  try {
    await helpers.httpRequest({ method: 'HEAD', url, timeout: 5000 });
    return url;
  } catch (error) {
    return null;
  }
}
function rememberProduct(phone, id) {
  const store = $getWorkflowStaticData('global');
  store.ctx = store.ctx || {};
  store.ctx[phone] = { product: id, at: Date.now() };
}
function productRows(list) {
  return list.slice(0, 10).map(item => ({
    id: 'prod_' + item.id,
    title: item.name,
    description: `${shekels(item.price)} · ${stockLabel(item.stock)}`,
  }));
}
function stockLabel(stock) {
  if (stock <= 0) return 'אזל';
  if (stock <= 5) return 'נשארו מעט';
  return 'במלאי';
}
function shekels(amount) {
  return Math.round(amount * 100) / 100 + ' ₪';
}

// ── סיכום הזמנה ──────────────────────────────────────────────
// לפני כל הזמנה — סיכום ובקשת אישור: [כן, להזמין] [ביטול].
// מגיע לכאן מלחיצה על "להזמין", או מ"טוב תזמין" בטקסט חופשי (המוצר מההקשר).
// אם המוצר אזל או שאין מספיק במלאי — מציעים חלופה, ולא ממשיכים לאישור.

const customer = $('זיהוי לקוח').first().json;
const input = $input.first().json;
const { catalog } = input;

const product = catalog.find(item => item.id === (input.product || input.ctxProduct));
const qty = Math.min(10, Math.max(1, Number(input.qty) || 1));

if (!product || product.stock <= 0) {
  return [
    reply('list', {
      button: 'לבחירת מוצר',
      section: 'מוצרים',
      text: product
        ? `${product.name} אזל כרגע 😕 אפשר לבחור מוצר אחר:`
        : 'איזה מוצר להזמין? בחרו מהרשימה 👇',
      rows: productRows(catalog),
    }),
  ];
}

rememberProduct(customer.phone, product.id);

if (qty > product.stock) {
  return [
    reply('buttons', {
      text: `אין במלאי מספיק ${product.name} לכמות של ${qty} 😕 אפשר להזמין יחידה אחת, ונציג יבדוק איתכם את השאר.`,
      buttons: [
        { id: 'order_' + product.id, title: 'להזמין יחידה אחת' },
        { id: 'route_sales', title: 'מוצרים נוספים' },
      ],
    }),
  ];
}

const orderedBy = customer.name && customer.name !== 'לקוח' ? customer.name : 'הטלפון הזה';

return [
  reply('buttons', {
    text: [
      'לסיכום:',
      `${product.name} × ${qty} — ${shekels(product.price * qty)}`,
      `על שם ${orderedBy}.`,
      '',
      'אין תשלום בוואטסאפ: אחרי השליחה נציג יחזור אליכם לתיאום תשלום ומשלוח. לשלוח את ההזמנה?',
    ].join('\n'),
    buttons: [
      // הכמות עוברת בתוך מזהה הכפתור — כך האישור לא תלוי בזיכרון
      { id: `confirm_${product.id}_q${qty}`, title: 'כן, להזמין' },
      { id: 'cancel', title: 'ביטול' },
    ],
  }),
];

function reply(kind, fields) {
  return { json: { phone: customer.phone, route: 'order', kind, ...fields } };
}
function rememberProduct(phone, id) {
  const store = $getWorkflowStaticData('global');
  store.ctx = store.ctx || {};
  store.ctx[phone] = { product: id, at: Date.now() };
}
function productRows(list) {
  return list.slice(0, 10).map(item => ({
    id: 'prod_' + item.id,
    title: item.name,
    description: `${shekels(item.price)} · ${stockLabel(item.stock)}`,
  }));
}
function stockLabel(stock) {
  if (stock <= 0) return 'אזל';
  if (stock <= 5) return 'נשארו מעט';
  return 'במלאי';
}
function shekels(amount) {
  return Math.round(amount * 100) / 100 + ' ₪';
}

// ── שורת הזמנה ───────────────────────────────────────────────
// הלקוח אישר. המחיר והמלאי נבדקים שוב מול הגיליון ברגע האישור —
// לא מסתמכים על מה שנאמר בשיחה, ולא על מה שהמודל כתב.
// פלט: { valid: true, ...שורה לגיליון ההזמנות, _pid, _newStock } או { valid: false }

const customer = $('זיהוי לקוח').first().json;
const input = $input.first().json;

const product = input.catalog.find(item => item.id === input.product);
const qty = Math.min(10, Math.max(1, Number(input.qty) || 1));

if (!product || product.stock < qty) {
  return [{ json: { valid: false, product: input.product } }];
}

const total = product.price * qty;

return [
  {
    json: {
      valid: true,
      // שדות עזר לעדכון המלאי. מוסרים לפני הכתיבה לגיליון ("שדות הזמנה")
      _pid: product.id,
      _newStock: product.stock - qty,
      // עמודות גיליון ההזמנות
      order_id: 'O-' + $now.setZone('Asia/Jerusalem').toFormat('yyMMddHHmmss'),
      created_at: customer.received_at,
      user_id: customer.user_id,
      customer_name: customer.name,
      phone: customer.phone,
      items: `${product.id}×${qty} ${product.name}`,
      subtotal_ils: total,
      discount_pct: 0,
      total_ils: total,
      status: 'new',
      rep_notes: 'הזמנה מהבוט בוואטסאפ',
    },
  },
];

// ── שדות הזמנה ───────────────────────────────────────────────
// רק עמודות גיליון ההזמנות — שדות העזר של המלאי אינם נכתבים לגיליון.

const { valid, _pid, _newStock, ...orderRow } = $input.first().json;

return [{ json: orderRow }];

// ── מלאי חדש ─────────────────────────────────────────────────
// הזמנה מורידה מלאי מיד, בלשונית products.
// ביטול הזמנה אינו מחזיר מלאי אוטומטית — הנציג מעדכן בגיליון.

const order = $('שורת הזמנה').first().json;

return [{ json: { id: order._pid, stock: Math.max(0, order._newStock) } }];

// ── אישור הזמנה ──────────────────────────────────────────────
// ההזמנה נכתבה והמלאי ירד. מאשרים ללקוח ומנקים את המוצר מההקשר.

const customer = $('זיהוי לקוח').first().json;
const order = $('שדות הזמנה').first().json;

forgetProduct(customer.phone);

// items = "P-002×3 בלוק יוגה מקצף" → "בלוק יוגה מקצף × 3"
const item = order.items.replace(/^(\S+)×(\d+) (.+)$/, '$3 × $2');

return [
  {
    json: {
      phone: customer.phone,
      route: 'order',
      kind: 'text',
      text: [
        `ההזמנה נשלחה ✅ (מספר ${order.order_id})`,
        `${item} — ${order.total_ils} ₪`,
        'נציג יחזור אליכם כאן לתיאום תשלום ומשלוח. תודה! 🙏',
      ].join('\n'),
    },
  },
];

function forgetProduct(phone) {
  const store = $getWorkflowStaticData('global');
  if (store.ctx) delete store.ctx[phone];
}

// ── הזמנה נכשלה ──────────────────────────────────────────────
// בין הסיכום לאישור המוצר אזל (או הוסר מהקטלוג). לא נכתבה הזמנה.

const customer = $('זיהוי לקוח').first().json;

return [
  {
    json: {
      phone: customer.phone,
      route: 'order',
      kind: 'text',
      text: 'אופס, המוצר כבר לא זמין להזמנה 😕 אפשר לכתוב "מוצרים" כדי לבחור מוצר אחר.',
    },
  },
];

// ── ביטול הזמנה ──────────────────────────────────────────────
// הלקוח לחץ "ביטול" בסיכום. לא נכתב דבר, והמוצר יוצא מההקשר.

const customer = $('זיהוי לקוח').first().json;

const store = $getWorkflowStaticData('global');
if (store.ctx) delete store.ctx[customer.phone];

return [
  {
    json: {
      phone: customer.phone,
      route: 'order',
      kind: 'text',
      text: 'אין בעיה, לא שלחתי כלום 🙂 אפשר לכתוב לי בכל שאלה.',
    },
  },
];

// ── בקשת פירוט ───────────────────────────────────────────────
// הלקוח בחר "שירות לקוחות" מהתפריט, בלי לכתוב מה הבעיה. מבקשים פירוט;
// ההודעה הבאה שלו תסווג כ-support ותפתח פנייה.

const customer = $input.first().json;

return [
  {
    json: {
      phone: customer.phone,
      route: 'support',
      kind: 'text',
      text: 'בשמחה 🙏 ספרו לי במה מדובר — איזה מוצר או איזו הזמנה, ומה הבעיה — ואעביר לנציג.',
    },
  },
];

// ── שורת פנייה ───────────────────────────────────────────────
// פנייה חדשה לגיליון השירות (לשונית tickets).
// הפנייה הפתוחה נזכרת 30 דקות: תמונה שתגיע בזמן הזה תצטרף אליה ("פנייה עם תמונה").

const customer = $input.first().json;
const ticketId = 'S-' + Date.now();

const store = $getWorkflowStaticData('global');
store.tickets = store.tickets || {};
store.tickets[customer.phone] = { id: ticketId, at: Date.now() };

return [
  {
    json: {
      ticket_id: ticketId,
      created_at: customer.received_at,
      phone: customer.phone,
      customer_name: customer.name,
      message: customer.text,
      images: '',
      image_paths: '',
      status: 'new',
      rep_notes: '',
    },
  },
];

// ── אישור פנייה ──────────────────────────────────────────────
// הפנייה נכתבה לגיליון. מאשרים ללקוח ומזמינים אותו לשלוח תמונה.

const customer = $('זיהוי לקוח').first().json;
const { ticket_id } = $('שורת פנייה').first().json;

const thanks = customer.name && customer.name !== 'לקוח' ? `תודה, ${customer.name}!` : 'תודה!';

return [
  {
    json: {
      phone: customer.phone,
      route: 'support',
      kind: 'text',
      text: [
        `${thanks} פתחתי פנייה (${ticket_id}), ונציג יחזור אלייך כאן בוואטסאפ בהקדם 🙏`,
        'אם יש תמונה של המוצר או של החבילה — אפשר לשלוח אותה עכשיו, והיא תצורף לפנייה.',
      ].join('\n'),
    },
  },
];

// ── פנייה עם תמונה ───────────────────────────────────────────
// התמונה כבר בדלי הפרטי support-media, ויש לה קישור חתום ל-30 יום.
// כאן מחליטים לאן היא שייכת:
//   append — יש פנייה פתוחה של הטלפון הזה מ-30 הדקות האחרונות → מצרפים אליה
//   new    — אין → פותחים פנייה חדשה
// אם ההורדה או ההעלאה נכשלו, url ריק — והפנייה נפתחת בכל זאת, עם הערה.

const customer = $('זיהוי לקוח').first().json;
const upload = $('Supabase — העלאה').first().json; // { Key: "support-media/<phone>/<id>.jpg" }
const signed = $input.first().json; // { signedURL: "/object/sign/..." }

const STORAGE = 'https://owvvkwxzjuglrfeuujez.supabase.co/storage/v1';
const HALF_HOUR = 30 * 60 * 1000;

const path = upload.Key ? String(upload.Key).replace(/^support-media\//, '') : '';
const url = signed.signedURL ? STORAGE + signed.signedURL : '';

const store = $getWorkflowStaticData('global');
store.tickets = store.tickets || {};
const openTicket = store.tickets[customer.phone];

const append = Boolean(openTicket && Date.now() - openTicket.at < HALF_HOUR);
const ticketId = append ? openTicket.id : 'S-' + Date.now();
store.tickets[customer.phone] = { id: ticketId, at: Date.now() };

return [
  {
    json: {
      mode: append ? 'append' : 'new',
      ticket_id: ticketId,
      url,
      path,
      caption: customer.caption || '',
      phone: customer.phone,
      name: customer.name,
      received_at: customer.received_at,
    },
  },
];

// ── שורת פנייה מתמונה ────────────────────────────────────────
// פנייה חדשה שנפתחה מתמונה. הכיתוב של התמונה הוא ההודעה.

const ticket = $input.first().json;

let message = ticket.caption;
if (!message) message = ticket.url ? '(תמונה)' : '(תמונה — השמירה נכשלה)';

return [
  {
    json: {
      ticket_id: ticket.ticket_id,
      created_at: ticket.received_at,
      phone: ticket.phone,
      customer_name: ticket.name,
      message,
      images: ticket.url,
      image_paths: ticket.path,
      status: 'new',
      rep_notes: '',
    },
  },
];

// ── אישור פנייה מתמונה ───────────────────────────────────────

const customer = $('זיהוי לקוח').first().json;
const ticket = $('פנייה עם תמונה').first().json;

const name = customer.name && customer.name !== 'לקוח' ? `, ${customer.name}` : '';
let lines;

if (ticket.url) {
  lines = [
    `קיבלתי את התמונה 📷 תודה${name}!`,
    `פתחתי פנייה (${ticket.ticket_id}), ונציג יחזור אלייך כאן בוואטסאפ בהקדם.`,
  ];
  if (!ticket.caption) {
    lines.push('אפשר לכתוב לי במה מדובר, ולשלוח עוד תמונות — הכול יצורף לפנייה.');
  }
} else {
  lines = [
    `לא הצלחתי לשמור את התמונה 🙏 פתחתי פנייה (${ticket.ticket_id}), ונציג יחזור אלייך כאן בהקדם.`,
  ];
}

return [
  { json: { phone: customer.phone, route: 'support', kind: 'text', text: lines.join('\n') } },
];

// ── צירוף לפנייה ─────────────────────────────────────────────
// מוסיף את התמונה לשורה הקיימת בגיליון: כל קישור בשורה משלו בתוך התא.
// הכיתוב, אם יש, מתווסף להודעה.
// פלט: העמודות לעדכון, לפי ticket_id

const ticket = $('פנייה עם תמונה').first().json;
const rows = $input.all().map(item => item.json);
const row = rows.find(r => String(r.ticket_id) === ticket.ticket_id) || {};

// מוסיף שורה לתא קיים, בלי שורות ריקות
const addLine = (cell, line) => [String(cell || '').trim(), line].filter(Boolean).join('\n');

const update = {
  ticket_id: ticket.ticket_id,
  images: addLine(row.images, ticket.url),
  image_paths: addLine(row.image_paths, ticket.path),
};
if (ticket.caption) update.message = addLine(row.message, ticket.caption);

return [{ json: update }];

// ── אישור צירוף ──────────────────────────────────────────────

const customer = $('זיהוי לקוח').first().json;
const ticket = $('פנייה עם תמונה').first().json;

const text = ticket.url
  ? `קיבלתי 📷 צירפתי את התמונה לפנייה ${ticket.ticket_id}.`
  : `לא הצלחתי לשמור את התמונה 🙏 נציג יחזור אלייך בפנייה ${ticket.ticket_id}.`;

return [{ json: { phone: customer.phone, route: 'support', kind: 'text', text } }];

