// ── תשובת כושר ───────────────────────────────────────────────
// התשובה של יועץ הכושר (OpenAI), כמו שהיא. אם הקריאה נכשלה — הודעת גיבוי.

const customer = $('זיהוי לקוח').first().json;
const answer = $input.first().json?.choices?.[0]?.message?.content;

const text =
  typeof answer === 'string' && answer.trim()
    ? answer.trim()
    : 'סליחה, משהו השתבש אצלי 🙏 נציג יחזור אלייך כאן בהקדם.';

return [{ json: { phone: customer.phone, route: 'fitness', kind: 'text', text } }];

// ── סטטוס משלוח ──────────────────────────────────────────────
// ההזמנה האחרונה של המספר שכתב, מגיליון ההזמנות.
// רק הזמנות של אותו טלפון — לא חושפים הזמנות של מספר אחר.

const customer = $('זיהוי לקוח').first().json;

const STATUS = {
  new: 'התקבלה וממתינה לנציג',
  in_progress: 'בטיפול',
  done: 'הושלמה',
  cancelled: 'בוטלה',
};

const myOrders = $input
  .all()
  .map(item => item.json)
  .filter(order => order.order_id && String(order.items || '').trim() !== '') // בלי פניות S- ישנות
  .filter(order => String(order.phone).replace(/\D/g, '') === customer.phone)
  .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));

let text;

if (myOrders.length === 0) {
  text =
    'לא מצאתי הזמנות על המספר הזה. אם הזמנת ממספר אחר, נציג יבדוק את זה איתך — אפשר לכתוב לי "נציג".';
} else {
  const latest = myOrders[0];
  const lines = [
    `ההזמנה האחרונה שלך (מספר ${latest.order_id}): ${latest.items}`,
    `סטטוס: ${STATUS[latest.status] ?? latest.status}.`,
  ];
  if (latest.status === 'new' || latest.status === 'in_progress') {
    lines.push('נציג יחזור אלייך לתיאום תשלום ומשלוח.');
  }
  text = lines.join('\n');
}

return [{ json: { phone: customer.phone, route: 'shipping', kind: 'text', text } }];

// ── קישור הרשמה ──────────────────────────────────────────────
// TODO: להחליף בקישור הרשמה אמיתי עם אסימון חד-פעמי שקשור לטלפון
// (docs/spec-shop-and-agent.md — "כניסה לבוט")

const customer = $('זיהוי לקוח').first().json;

return [
  {
    json: {
      phone: customer.phone,
      route: 'signup',
      kind: 'text',
      text: [
        'מי שמתאמן באפליקציה ומשלים את היעד השבועי מקבל 10% הנחה בחנות 💪',
        'להרשמה: https://example.com/signup',
        '(קישור זמני — יוחלף בקישור האמיתי)',
      ].join('\n'),
    },
  },
];

// ── שאלת הבהרה ───────────────────────────────────────────────
// פקיד הקבלה לא הבין מה הלקוח רוצה (או שזו רק ברכה) — מציגים את התפריט.

const customer = $('זיהוי לקוח').first().json;

const MENU = [
  { id: 'route_sales', title: 'מכירות', description: 'מוצרים, מחירים ומלאי' },
  { id: 'route_support', title: 'שירות לקוחות', description: 'בעיה בהזמנה או במוצר' },
  { id: 'route_fitness', title: 'ייעוץ כושר', description: 'טיפים כלליים לאימון' },
  { id: 'route_shipping', title: 'מידע על משלוח', description: 'איפה ההזמנה שלי?' },
  { id: 'route_signup', title: 'הרשמה לאפליקציה', description: 'הנחת כושר למתאמנים' },
];

const hi = customer.name && customer.name !== 'לקוח' ? `היי ${customer.name}! ` : 'היי! ';

return [
  {
    json: {
      phone: customer.phone,
      route: 'unclear',
      kind: 'list',
      button: 'אפשרויות',
      text: hi + 'במה אפשר לעזור? אפשר לבחור מהרשימה או פשוט לכתוב לי.',
      rows: MENU,
    },
  },
];

// ── בניית הודעת וואטסאפ ──────────────────────────────────────
// כל התשובות מגיעות לכאן באותו מבנה: { phone, route, kind, text, ... }
// ומכאן יוצא גוף הבקשה ל-WhatsApp Cloud API, לפי kind:
//   text    — הודעת טקסט
//   list    — רשימה: { button, section, rows[] }
//   buttons — כפתורי תשובה: { buttons[], image? }
//
// מגבלות Meta (נבדקו בתיעוד הרשמי, 23 בספטמבר 2026):
//   List    — כפתור 20 תווים, כותרת שורה 24, תיאור 72, עד 10 שורות, גוף 4096
//   Buttons — עד 3 כפתורים, כותרת 20, גוף 1024

const reply = $input.first().json;

const base = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: reply.phone,
};

let payload;

if (reply.kind === 'list') {
  payload = {
    ...base,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: cut(reply.text, 4096) },
      action: {
        button: cut(reply.button || 'אפשרויות', 20),
        sections: [
          {
            title: cut(reply.section || 'במה אפשר לעזור?', 24),
            rows: reply.rows.slice(0, 10).map(row => ({
              id: row.id,
              title: cut(row.title, 24),
              ...(row.description ? { description: cut(row.description, 72) } : {}),
            })),
          },
        ],
      },
    },
  };
} else if (reply.kind === 'buttons') {
  payload = {
    ...base,
    type: 'interactive',
    interactive: {
      type: 'button',
      ...(reply.image ? { header: { type: 'image', image: { link: reply.image } } } : {}),
      body: { text: cut(reply.text, 1024) },
      action: {
        buttons: reply.buttons.slice(0, 3).map(button => ({
          type: 'reply',
          reply: { id: button.id, title: cut(button.title, 20) },
        })),
      },
    },
  };
} else {
  payload = {
    ...base,
    type: 'text',
    text: { preview_url: false, body: cut(reply.text, 4096) },
  };
}

return [{ json: { ...reply, payload } }];

function cut(value, max) {
  return String(value).slice(0, max);
}

// ── רישום שיחה ───────────────────────────────────────────────
// שתי שורות ל-chat_log: ההודעה שנכנסה, והתשובה שיצאה (או השגיאה בשליחה).
// בנוסף — זיכרון שיחה לסוכנים: 8 ההודעות האחרונות לכל טלפון, ב-static data.

const incoming = $('פענוח ההודעה').first().json;
const customer = $('זיהוי לקוח').first().json;
const outgoing = $('בניית הודעת וואטסאפ').first().json;
const sendResult = $input.first().json;

const sent = Array.isArray(sendResult.messages) && sendResult.messages.length > 0;
const now = $now.setZone('Asia/Jerusalem').toFormat('yyyy-MM-dd HH:mm:ss');

// ── זיכרון שיחה ──
const store = $getWorkflowStaticData('global');
store.hist = store.hist || {};
store.hist[incoming.phone] = (store.hist[incoming.phone] || [])
  .concat([
    { role: 'user', text: String(incoming.text), at: Date.now() },
    { role: 'agent', text: String(outgoing.text), at: Date.now() },
  ])
  .slice(-8);

// ── שורות ל-chat_log ──
const error = sent
  ? ''
  : `  [שליחה נכשלה: ${JSON.stringify(sendResult.error ?? sendResult).slice(0, 200)}]`;

return [
  {
    json: {
      timestamp: incoming.received_at,
      phone: incoming.phone,
      user_id: customer.user_id,
      role: 'user',
      message: incoming.text,
      tool_called: '',
    },
  },
  {
    json: {
      timestamp: now,
      phone: incoming.phone,
      user_id: customer.user_id,
      role: 'agent',
      message: String(outgoing.text) + error,
      tool_called: 'route:' + outgoing.route,
    },
  },
];
